package payflow

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"math"
	"os"
	"path/filepath"
)

// atomicWrite 将 v 以 JSON 原子写入 path：
//  1. 写入同目录临时文件并 fsync；
//  2. rename 覆盖目标文件（同文件系统内原子）；
