1	package payflow
2	
3	import (
4		"os"
5		"sync/atomic"
6		"testing"
7	)
8	
9	// 本文件回归“句柄关闭与付款交错”时调用者可观察到的行为：
10	//
11	//   - 关闭只结束该句柄本身：关闭后经它付款/查询一律 ledger_closed，
12	//     不扣款、不留成功记录、不被当成空查询；重复关闭仍成功。
13	//   - 同进程的其他句柄继续正常使用：余额、成功记录、幂等与冲突判定
14	//     不受某个句柄关闭的影响。
15	//   - 唯一句柄在一笔付款“已开始、保存尚未完成”时关闭并随即重开：
16	//     在途付款不被取消，新句柄面对的是该操作结束后的完整状态——
17	//     成功则余额/记录/序号/去重资格全部生效，失败则彻底回滚，
18	//     失败编号仍可用于之后的合法付款。
19	//
20	// 交错窗口由 gatedPersistHook 在持久化调用处确定性地制造，
21	// 不依赖时序调度，因此可用 -race 稳定重复运行。
22	
23	// gatedPersistHook 在第一次持久化调用处制造“保存尚未完成”的窗口：
24	// 首次 FailNextPersist 进入后阻塞在 entered 上，直到测试 close(release)，
25	// 随后返回 fail（true 表示本次保存失败）；窗口之后的所有持久化一律放行，
26	// 使重开句柄上的后续操作正常落盘。calls 记录持久化被触发的总次数，
27	// 用于证明 Close 本身不产生任何写入（不生成业务历史）。
28	type gatedPersistHook struct {
29		active  atomic.Bool
30		entered chan struct{}
31		release chan struct{}
32		fail    bool
33		calls   atomic.Int64
34	}
35	
36	func newGatedPersistHook(fail bool) *gatedPersistHook {
37		h := &gatedPersistHook{
38			entered: make(chan struct{}),
39			release: make(chan struct{}),
40			fail:    fail,
41		}
42		h.active.Store(true)
43		return h
44	}
45	
46	func (h *gatedPersistHook) FailNextPersist() bool {
47		h.calls.Add(1)
48		if !h.active.CompareAndSwap(true, false) {
49			return false // 窗口之后的持久化全部成功
50		}
51		close(h.entered)
52		<-h.release
53		return h.fail
54	}
