57	// 错误必须明确（余额返回 0 但同时带错，不能被当成合法的空查询；
58	// Query 不得返回空快照代替错误），且不产生任何业务结果。
59	func assertClosedHandle(t *testing.T, l *Ledger) {
60		t.Helper()
61	
62		if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
63			intent("late", "aa", "usdc", 1),
64		}}); KindOf(err) != ErrClosed {
65			t.Fatalf("Submit on closed handle: want %s, got %v", ErrClosed, err)
66		}
67		if bal, err := l.Balance("aa", "usdc"); KindOf(err) != ErrClosed || bal != 0 {
