74			intent("late", "aa", "usdc", 1),
75		}}); KindOf(err) != ErrClosed {
76			t.Fatalf("Preview on closed handle: want %s, got %v", ErrClosed, err)
77		}
78		if _, err := l.Refund(RefundBatch{Refunds: []RefundRequest{
79			refundReq("r-late", "p1", "x"),
80		}}); KindOf(err) != ErrClosed {
