100	// 句柄关闭后：所有操作返回 ledger_closed，不扣款、不留记录；
101	// 重复关闭同一已关闭句柄仍成功；账本文件可被重新打开且状态原样。
102	func TestClosedHandleRejectsEveryOperation(t *testing.T) {
103		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
104		l, err := Open(path)
105		if err != nil {
106			t.Fatal(err)
107		}
108	
109		if err := l.Close(); err != nil {
110			t.Fatalf("first close: %v", err)
111		}
112		// 重复关闭必须仍然成功（关闭是幂等的）。
113		if err := l.Close(); err != nil {
114			t.Fatalf("repeated close must succeed, got %v", err)
115		}
116	
117		assertClosedHandle(t, l)
118	
119		// 关闭不改动磁盘：重开得到初始余额与空历史，关闭本身不留任何业务痕迹。
