133	// 同进程持有多个句柄时，关闭其中一个只结束该句柄：其他句柄继续看到
134	// 共享余额与成功记录，已成功编号仍是 duplicate（携带原记录）或 conflict，
135	// 旧编号不会因关闭重新获得扣款资格，后续成功付款继续正常占用序号。
136	func TestCloseOneHandleKeepsOtherHandleWorking(t *testing.T) {
137		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
138		l1, err := Open(path)
139		if err != nil {
140			t.Fatal(err)
141		}
142		t.Cleanup(func() { l1.Close() })
143		l2, err := Open(path)
144		if err != nil {
145			t.Fatal(err)
146		}
147		t.Cleanup(func() { l2.Close() })
148	
149		first, err := l1.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
150			intent("p1", "aa", "usdc", 70),
151		}})
152		if err != nil {
153			t.Fatal(err)
154		}
155		if first.Results[0].Status != StatusSettled {
156			t.Fatalf("setup settle: %+v", first.Results[0])
157		}
158		rec := *first.Results[0].Record
159	
160		// 关闭其中一个句柄：它立即不可用，但不取消任何已完成或在途的状态。
161		if err := l1.Close(); err != nil {
162			t.Fatal(err)
163		}
164		assertClosedHandle(t, l1)
165	
166		// 另一句柄照常工作：看到 100-70=30 的共享余额。
167		if bal, _ := l2.Balance("aa", "usdc"); bal != 30 {
168			t.Fatalf("surviving handle balance=%d want 30", bal)
169		}
170		// 同编号同字段：duplicate 且逐字返回原记录，不再扣款。
171		dup, err := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
172			intent("p1", "aa", "usdc", 70),
173		}})
174		if err != nil {
175			t.Fatal(err)
176		}
177		d := dup.Results[0]
178		if d.Status != StatusDuplicate || d.Record == nil || *d.Record != rec {
179			t.Fatalf("retry on surviving handle want duplicate with original record %+v, got %+v", rec, d)
180		}
181		if bal, _ := l2.Balance("aa", "usdc"); bal != 30 {
182			t.Fatalf("duplicate charged again: balance=%d want 30", bal)
183		}
184		// 同编号改字段：conflict，旧编号不重新获得扣款资格。
185		cf, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
186			intent("p1", "aa", "usdc", 71),
187		}})
188		if cf.Results[0].Status != StatusConflict {
189			t.Fatalf("changed retry want conflict, got %+v", cf.Results[0])
190		}
191		// 余额 30：另付 60 余额不足。
192		funds, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
193			intent("p2", "aa", "usdc", 60),
194		}})
195		if funds.Results[0].Status != StatusFunds {
196			t.Fatalf("60 against balance 30 want insufficient_balance, got %+v", funds.Results[0])
197		}
198		// 新编号付 30 成功并占用下一个序号。
199		ok, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
200			intent("p3", "aa", "usdc", 30),
201		}})
202		if ok.Results[0].Status != StatusSettled || ok.Results[0].Record.Seq != 2 {
203			t.Fatalf("next payment want settled with seq 2, got %+v", ok.Results[0])
204		}
205		if bal, _ := l2.Balance("aa", "usdc"); bal != 0 {
206			t.Fatalf("balance=%d want 0", bal)
207		}
208	
209		// 关闭后重新打开（l2 仍在）：新句柄加入同一注册表，看到完整状态。
210		l3, err := Open(path)
211		if err != nil {
212			t.Fatal(err)
213		}
214		t.Cleanup(func() { l3.Close() })
215		snap, _ := l3.Query()
216		if len(snap.Settlements) != 2 ||
217			snap.Settlements[0].ID != "p1" || snap.Settlements[0].Seq != 1 ||
218			snap.Settlements[1].ID != "p3" || snap.Settlements[1].Seq != 2 {
219			t.Fatalf("reopened handle history: %+v", snap.Settlements)
220		}
221		dup3, _ := l3.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
222			intent("p1", "aa", "usdc", 70),
223		}})
224		if dup3.Results[0].Status != StatusDuplicate || dup3.Results[0].Record.Seq != 1 {
225			t.Fatalf("duplicate after reopen: %+v", dup3.Results[0])
226		}
227	
228		// 全部句柄关闭后再从磁盘恢复，结果必须一致。
229		if err := l2.Close(); err != nil {
230			t.Fatal(err)
231		}
232		if err := l3.Close(); err != nil {
233			t.Fatal(err)
234		}
235		l4 := openOrFail(t, path)
236		if bal, _ := l4.Balance("aa", "usdc"); bal != 0 {
237			t.Fatalf("disk-reopened balance=%d want 0", bal)
238		}
239		snap4, _ := l4.Query()
240		if len(snap4.Settlements) != 2 {
241			t.Fatalf("disk-reopened history=%+v", snap4.Settlements)
242		}
243	}
