245	// 核心回归（成功分支）：唯一打开的句柄在一笔付款已经开始、保存尚未
246	// 完成时关闭，调用者随即重开同一账本。在途付款必须按原请求完成，
247	// 新句柄面对的是这笔操作结束后的完整状态：
248	// 余额 100、费率 0、付款 70 成功后，新句柄看到余额 30 与唯一成功记录；
249	// 重提同编号同字段得到 duplicate 与原记录，另付 60 得到 insufficient_balance；
250	// 成功序号与原记录一致，关闭本身不触发持久化、不生成任何业务历史。
251	func TestReopenDuringInFlightPaymentCommitsToNewHandle(t *testing.T) {
252		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
253		l1, err := Open(path)
254		if err != nil {
255			t.Fatal(err)
256		}
257		t.Cleanup(func() { l1.Close() })
258	
259		hook := newGatedPersistHook(false) // 窗口放行后保存成功
260		SetFailHook(l1, hook)
261		t.Cleanup(func() { SetFailHook(l1, nil) })
262	
263		type outcome struct {
264			res *BatchResult
265			err error
266		}
267		done := make(chan outcome, 1)
268		go func() {
269			res, err := l1.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
270				intent("p1", "aa", "usdc", 70),
271			}})
272			done <- outcome{res, err}
273		}()
274		<-hook.entered // 付款已进入保存，且保存尚未完成
275	
276		// 在保存窗口内关闭唯一旧句柄，并立即重新打开同一账本。
277		if err := l1.Close(); err != nil {
278			t.Fatalf("close during in-flight payment: %v", err)
279		}
280		l2, err := Open(path)
281		if err != nil {
282			t.Fatalf("reopen while payment in flight: %v", err)
283		}
284		t.Cleanup(func() { l2.Close() })
285	
286		// 放行保存：在途付款不被关闭取消，按原请求成功。
287		close(hook.release)
288		got := <-done
289		if got.err != nil {
290			t.Fatalf("in-flight submit error: %v", got.err)
291		}
292		r := got.res.Results[0]
293		if r.Status != StatusSettled || r.Record == nil {
294			t.Fatalf("in-flight payment want settled, got %+v", r)
295		}
296		if r.Record.Seq != 1 || r.Record.Amount != 70 || r.Record.Charged != 70 || r.Record.FeeBps != 0 {
297			t.Fatalf("in-flight settlement record: %+v", r.Record)
298		}
299	
300		// 旧句柄在关闭后不复活：后续使用一律 ledger_closed。
301		assertClosedHandle(t, l1)
302	
303		// 新句柄看到的是操作结束后的完整状态：余额 30、唯一成功记录。
304		if bal, _ := l2.Balance("aa", "usdc"); bal != 30 {
305			t.Fatalf("new handle balance=%d want 30", bal)
306		}
307		snap, _ := l2.Query()
308		if len(snap.Settlements) != 1 {
309			t.Fatalf("new handle settlements=%+v want exactly one record", snap.Settlements)
310		}
311		if sr := snap.Settlements[0]; sr.ID != "p1" || sr.Seq != 1 || sr.Amount != 70 || sr.Charged != 70 {
312			t.Fatalf("new handle record mismatch: %+v", sr)
313		}
314		if len(snap.Refunds) != 0 {
315			t.Fatalf("close must not create refund history: %+v", snap.Refunds)
316		}
317	
318		// 重提同编号同字段：duplicate 且携带原记录（序号仍是 1）。
319		dup, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
320			intent("p1", "aa", "usdc", 70),
321		}})
322		if dup.Results[0].Status != StatusDuplicate ||
323			dup.Results[0].Record == nil || dup.Results[0].Record.Seq != 1 {
324			t.Fatalf("retry committed payment want duplicate with seq-1 record, got %+v", dup.Results[0])
325		}
326		// 同编号不同字段：conflict。
327		cf, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
328			intent("p1", "aa", "usdc", 71),
329		}})
330		if cf.Results[0].Status != StatusConflict {
331			t.Fatalf("changed retry want conflict, got %+v", cf.Results[0])
332		}
333		// 另付 60：余额只有 30，必须不足——防止重开读到旧余额 100 后再次成功。
334		funds, _ := l2.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
335			intent("p2", "aa", "usdc", 60),
336		}})
337		if funds.Results[0].Status != StatusFunds {
338			t.Fatalf("60 against balance 30 want insufficient_balance, got %+v", funds.Results[0])
339		}
340		if bal, _ := l2.Balance("aa", "usdc"); bal != 30 {
341			t.Fatalf("balance after failed attempts=%d want 30", bal)
342		}
343	
344		// 关闭本身不落盘：整个交错过程只发生过那一次在途付款的持久化。
345		if n := hook.calls.Load(); n != 1 {
346			t.Fatalf("persist calls=%d want 1 (close must not write)", n)
347		}
348		// 磁盘文件与新句柄状态一致：余额 30、唯一记录。
349		if bal, n := persistedBalanceAndCount(t, path, "aa", "usdc"); bal != 30 || n != 1 {
350			t.Fatalf("persisted state: bal=%d records=%d, want 30/1", bal, n)
351		}
352	
353		// 全部关闭后再从磁盘重开：仍读到操作结束后的完整状态，旧余额不复活。
354		if err := l2.Close(); err != nil {
355			t.Fatal(err)
356		}
357		l3 := openOrFail(t, path)
358		if bal, _ := l3.Balance("aa", "usdc"); bal != 30 {
359			t.Fatalf("disk-reopened balance=%d want 30", bal)
360		}
361		snap3, _ := l3.Query()
362		if len(snap3.Settlements) != 1 || snap3.Settlements[0].ID != "p1" || snap3.Settlements[0].Seq != 1 {
363			t.Fatalf("disk-reopened history: %+v", snap3.Settlements)
364		}
365		dup3, _ := l3.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
366			intent("p1", "aa", "usdc", 70),
367		}})
368		if dup3.Results[0].Status != StatusDuplicate || dup3.Results[0].Record.Seq != 1 {
369			t.Fatalf("duplicate after disk reopen: %+v", dup3.Results[0])
370		}
371		retry60, _ := l3.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
372			intent("p2", "aa", "usdc", 60),
373		}})
374		if retry60.Results[0].Status != StatusFunds {
375			t.Fatalf("60 after disk reopen want insufficient_balance, got %+v", retry60.Results[0])
376		}
377	}
