		{Account: "aa", Asset: "usdc", Balance: 0},
		{Account: "aa", Asset: "eth", Balance: math.MaxInt64},
	}); err != nil {
		t.Fatalf("valid init: %v", err)
	}

	// 重复初始化报错，不覆盖。
	err := CreateLedger(path, []BalanceInit{{Account: "bb", Asset: "usdc", Balance: 1}})
