	if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
		t.Fatalf("history overwritten: aa/usdc=%d", bal)
	}
	if bal, _ := l.Balance("bb", "usdc"); bal != 0 {
		t.Fatalf("re-init leaked new account, bb/usdc=%d", bal)
	}
