352	func TestPersistenceAcrossHandlesAndReopen(t *testing.T) {
353		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
354	
355		l1 := openOrFail(t, path)
356		res, _ := l1.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 300)}})
357		if res.Results[0].Status != StatusSettled {
358			t.Fatalf("settle: %+v", res.Results[0])
359		}
360	
361		// 同进程内再次 Open 同一路径，必须看到同一本账本的即时状态（共享而非重读）。
362		l2 := openOrFail(t, path)
363		if bal, _ := l2.Balance("aa", "usdc"); bal != 700 {
364			t.Fatalf("second handle sees stale balance %d", bal)
365		}
366	
367		// 关闭全部句柄，模拟程序重启后从磁盘恢复。
368		if err := l1.Close(); err != nil {
369			t.Fatal(err)
370		}
371		if err := l2.Close(); err != nil {
372			t.Fatal(err)
373		}
374		l3 := openOrFail(t, path)
375		if bal, _ := l3.Balance("aa", "usdc"); bal != 700 {
376			t.Fatalf("after reopen balance=%d want 700", bal)
377		}
378		snap, _ := l3.Query()
379		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p" || snap.Settlements[0].Charged != 300 {
380			t.Fatalf("after reopen records=%+v", snap.Settlements)
381		}
382	}
